import React, { useState, useEffect } from 'react';
import './App.css';

function App() {
  const [activeTab, setActiveTab] = useState('books');
  const [books, setBooks] = useState([]);
  const [users, setUsers] = useState([]);
  const [issues, setIssues] = useState([]);
  const [message, setMessage] = useState('');
  const [messageType, setMessageType] = useState('');

  const API_URL = 'http://localhost:3000/api';

  const showMessage = (msg, type) => {
    setMessage(msg);
    setMessageType(type);
    setTimeout(() => setMessage(''), 3000);
  };

  const loadBooks = async () => {
    try {
      const res = await fetch(`${API_URL}/books`);
      const data = await res.json();
      setBooks(data.books || []);
    } catch (error) {
      showMessage('Error loading books', 'error');
    }
  };

  const loadUsers = async () => {
    try {
      const res = await fetch(`${API_URL}/users`);
      const data = await res.json();
      setUsers(data.users || []);
    } catch (error) {
      showMessage('Error loading users', 'error');
    }
  };

  const loadIssues = async () => {
    try {
      const res = await fetch(`${API_URL}/issues`);
      const data = await res.json();
      setIssues(data.issues || []);
    } catch (error) {
      showMessage('Error loading issues', 'error');
    }
  };

  useEffect(() => {
    loadBooks();
    loadUsers();
    loadIssues();
  }, []);

  const handleCheckout = async (e) => {
    e.preventDefault();
    const formData = new FormData(e.target);
    try {
      const res = await fetch(`${API_URL}/issues`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          user_id: parseInt(formData.get('user_id')),
          book_id: parseInt(formData.get('book_id')),
          due_days: parseInt(formData.get('due_days'))
        })
      });

      if (res.ok) {
        showMessage('Book checked out!', 'success');
        e.target.reset();
        loadBooks();
        loadIssues();
      } else {
        showMessage('Error checking out', 'error');
      }
    } catch (error) {
      showMessage('Error: ' + error.message, 'error');
    }
  };

  const handleReturn = async (e) => {
    e.preventDefault();
    const formData = new FormData(e.target);
    try {
      const res = await fetch(`${API_URL}/returns`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          issue_id: parseInt(formData.get('issue_id')),
          returned_by_user_id: parseInt(formData.get('returned_by_user_id')),
          condition_notes: formData.get('condition_notes')
        })
      });

      if (res.ok) {
        showMessage('Book returned!', 'success');
        e.target.reset();
        loadBooks();
        loadIssues();
      } else {
        showMessage('Error returning', 'error');
      }
    } catch (error) {
      showMessage('Error: ' + error.message, 'error');
    }
  };

  const handleReserve = async (e) => {
    e.preventDefault();
    const formData = new FormData(e.target);
    try {
      const res = await fetch(`${API_URL}/reservations`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          user_id: parseInt(formData.get('user_id')),
          book_id: parseInt(formData.get('book_id')),
          expire_days: parseInt(formData.get('expire_days'))
        })
      });

      if (res.ok) {
        showMessage('Book reserved!', 'success');
        e.target.reset();
      } else {
        showMessage('Error reserving', 'error');
      }
    } catch (error) {
      showMessage('Error: ' + error.message, 'error');
    }
  };

  return (
    <div className="app">
      <div className="container">
        <h1>📚 Library Management System</h1>

        {message && <div className={`alert ${messageType}`}>{message}</div>}

        <div className="nav">
          <button className={activeTab === 'books' ? 'active' : ''} onClick={() => setActiveTab('books')}>
            📖 Books
          </button>
          <button className={activeTab === 'checkout' ? 'active' : ''} onClick={() => setActiveTab('checkout')}>
            📤 Checkout
          </button>
          <button className={activeTab === 'return' ? 'active' : ''} onClick={() => setActiveTab('return')}>
            📥 Return
          </button>
          <button className={activeTab === 'reserve' ? 'active' : ''} onClick={() => setActiveTab('reserve')}>
            🔖 Reserve
          </button>
          <button className={activeTab === 'issues' ? 'active' : ''} onClick={() => setActiveTab('issues')}>
            📋 Issues
          </button>
        </div>

        {activeTab === 'books' && (
          <div className="section">
            <h2>Available Books</h2>
            <div className="book-grid">
              {books.map(book => (
                <div key={book.book_id} className="card">
                  <h3>{book.title}</h3>
                  <p><strong>Author:</strong> {book.author}</p>
                  <p><strong>ISBN:</strong> {book.isbn}</p>
                  <span className={`status-badge ${book.status}`}>{book.status}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'checkout' && (
          <div className="section">
            <h2>Checkout Book</h2>
            <form onSubmit={handleCheckout} className="form">
              <div className="form-group">
                <label>User *</label>
                <select name="user_id" required>
                  <option value="">Select User</option>
                  {users.map(u => (
                    <option key={u.user_id} value={u.user_id}>{u.full_name}</option>
                  ))}
                </select>
              </div>
              <div className="form-group">
                <label>Book *</label>
                <select name="book_id" required>
                  <option value="">Select Book</option>
                  {books.filter(b => b.status === 'available').map(b => (
                    <option key={b.book_id} value={b.book_id}>{b.title}</option>
                  ))}
                </select>
              </div>
              <div className="form-group">
                <label>Due Days *</label>
                <input type="number" name="due_days" defaultValue="14" required />
              </div>
              <button type="submit" className="btn">Checkout</button>
            </form>
          </div>
        )}

        {activeTab === 'return' && (
          <div className="section">
            <h2>Return Book</h2>
            <form onSubmit={handleReturn} className="form">
              <div className="form-group">
                <label>Issue *</label>
                <select name="issue_id" required>
                  <option value="">Select Issue</option>
                  {issues.filter(i => i.status !== 'completed').map(i => (
                    <option key={i.issue_id} value={i.issue_id}>Issue #{i.issue_id}</option>
                  ))}
                </select>
              </div>
              <div className="form-group">
                <label>Returned By *</label>
                <select name="returned_by_user_id" required>
                  <option value="">Select Librarian</option>
                  {users.filter(u => u.role === 'librarian').map(u => (
                    <option key={u.user_id} value={u.user_id}>{u.full_name}</option>
                  ))}
                </select>
              </div>
              <div className="form-group">
                <label>Condition Notes</label>
                <input type="text" name="condition_notes" placeholder="Book condition" />
              </div>
              <button type="submit" className="btn">Process Return</button>
            </form>
          </div>
        )}

        {activeTab === 'reserve' && (
          <div className="section">
            <h2>Reserve Book</h2>
            <form onSubmit={handleReserve} className="form">
              <div className="form-group">
                <label>User *</label>
                <select name="user_id" required>
                  <option value="">Select User</option>
                  {users.map(u => (
                    <option key={u.user_id} value={u.user_id}>{u.full_name}</option>
                  ))}
                </select>
              </div>
              <div className="form-group">
                <label>Book *</label>
                <select name="book_id" required>
                  <option value="">Select Book</option>
                  {books.map(b => (
                    <option key={b.book_id} value={b.book_id}>{b.title}</option>
                  ))}
                </select>
              </div>
              <div className="form-group">
                <label>Expire Days *</label>
                <input type="number" name="expire_days" defaultValue="7" required />
              </div>
              <button type="submit" className="btn">Reserve</button>
            </form>
          </div>
        )}

        {activeTab === 'issues' && (
          <div className="section">
            <h2>Active Issues</h2>
            <div className="book-grid">
              {issues.filter(i => i.status !== 'completed').map(issue => (
                <div key={issue.issue_id} className="card">
                  <h3>Issue #{issue.issue_id}</h3>
                  <p><strong>User:</strong> {issue.user_id}</p>
                  <p><strong>Book:</strong> {issue.book_id}</p>
                  <p><strong>Due:</strong> {new Date(issue.due_at).toLocaleDateString()}</p>
                  <span className={`status-badge ${issue.status}`}>{issue.status}</span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default App;
